(()=>{'use strict';const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));let view='overview',edits={},done={};const stages=['Days 1–7 · Stabilise','Days 8–14 · Standardise','Days 15–30 · Optimise'];function model(){return result&&parsed?Ops.analyse(result,parsed,mapping):null;}function card(g){return '<article class="diagnosis-card"><div class="diagnosis-top"><strong>'+esc(g.rule)+'</strong><span class="badge '+esc(g.severity)+'">'+esc(g.severity)+'</span><span>'+g.items.length+' affected records</span></div><p><b>Observation</b> · '+esc(g.items[0].evidence)+'</p><p><b>Operational impact</b> · '+esc(g.meta.impact)+'</p><p><b>Root-cause hypothesis (unverified)</b> · '+esc(g.meta.hypothesis)+'</p><p><b>Recommendation</b> · '+esc(g.meta.fix)+'</p><p><b>Owner</b> · '+esc(g.meta.owner)+' · <b>Effort</b> '+g.meta.effort+'/5 · <b>Success metric</b> · '+esc(g.meta.metric)+'</p><details><summary>Inspect '+g.items.length+' supporting records</summary><div class="evidence-list">'+g.items.slice(0,100).map(i=>'<p><b>'+esc(i.id)+'</b> · '+esc(i.candidate)+' · '+esc(i.job)+' · '+esc(i.evidence)+'</p>').join('')+'</div></details></article>';}function render(){const m=model(),el=$('consultant-content');$('workspace-kind').textContent=demo?'CONSULTANT WORKSPACE · FICTIONAL DATA':'CONSULTANT WORKSPACE · LOCAL PSEUDONYMOUS DATA';if(!m){el.innerHTML='<p>Load the demo or a CSV to begin.</p>';return;}const coverage='<p class="method">'+esc(m.method)+'</p><p class="method"><b>Evidence limitations:</b> '+esc(m.unsupported.join('; '))+'. Unavailable checks must not be interpreted as passed.</p>';if(view==='overview'){el.innerHTML='<div class="score-hero"><div><small>OVERALL RECRUITING OPERATIONS HEALTH</small><strong>'+m.score+'<span>/100</span></strong><p>Deterministic issue-density index · '+esc(m.asOf)+'</p></div><div class="score-grid">'+Object.entries(m.scores).map(([k,v])=>'<div><span>'+esc(k)+'</span><b>'+v+'/100</b><div class="meter"><i style="width:'+v+'%"></i></div></div>').join('')+'</div></div><h3>Top three actions</h3>'+m.grouped.slice(0,3).map((g,i)=>'<div class="action-row"><b>0'+(i+1)+'</b><span>'+esc(g.meta.fix)+'</span><small>'+g.items.length+' records · '+esc(g.meta.owner)+'</small></div>').join('')+'<p><b>'+m.issues.filter(i=>i.severity==='High').length+'</b> critical · <b>'+m.issues.filter(i=>i.severity==='Medium').length+'</b> moderate · <b>'+m.issues.filter(i=>i.severity==='Low').length+'</b> low-priority record findings</p>'+coverage;}else if(view==='diagnosis'){el.innerHTML='<h3>Consultant’s diagnosis</h3><p class="muted">Observed records are evidence. Root causes remain hypotheses until validated with the customer.</p>'+m.grouped.map(card).join('')+coverage;}else if(view==='roadmap'){el.innerHTML='<h3>Prioritised 30-day improvement roadmap</h3><p class="muted">Order reflects severity, affected records, operational area and estimated effort. Edits and completion state remain in this browser session. Keep names and other personal details out of recommendation notes.</p>'+stages.map((name,index)=>'<section class="roadmap-phase"><h3>'+name+'</h3>'+m.grouped.filter(g=>Math.min(g.meta.phase,3)===index+1).map(g=>'<div class="roadmap-item"><label><input type="checkbox" data-complete="'+esc(g.rule)+'" '+(done[g.rule]?'checked':'')+'> Completed</label><textarea data-edit="'+esc(g.rule)+'" aria-label="Edit recommendation for '+esc(g.rule)+'">'+esc(edits[g.rule]??g.meta.fix)+'</textarea><small>'+esc(g.meta.owner)+' · '+g.items.length+' affected · Priority '+g.priority+'</small></div>').join('')+(index===2?'<p>Introduce recurring governance checks, reporting review and measurement of success metrics.</p>':'')+'</section>').join('');el.querySelectorAll('[data-complete]').forEach(x=>x.onchange=()=>done[x.dataset.complete]=x.checked);el.querySelectorAll('[data-edit]').forEach(x=>x.oninput=()=>edits[x.dataset.edit]=x.value);}else{el.innerHTML='<div id="printable-report"><h2>Recruiting Operations Health Check</h2><p>Independent consultant report · '+(demo?'Fictional demo data':'Pseudonymised local import — personal data')+' · '+esc(m.asOf)+'</p><h3>Executive summary</h3><p>Overall health index: <b>'+m.score+'/100</b>. '+m.grouped.length+' issue categories and '+m.issues.length+' record-level findings identified across available checks.</p><h3>Supporting evidence and recommendations</h3>'+m.grouped.map(g=>'<section><h4>'+esc(g.rule)+' · '+g.items.length+' records</h4><p>Evidence: '+esc(g.items[0].evidence)+'</p><p>Impact: '+esc(g.meta.impact)+'</p><p>Hypothesis (unverified): '+esc(g.meta.hypothesis)+'</p><p>Action: '+esc(edits[g.rule]??g.meta.fix)+' · Owner: '+esc(g.meta.owner)+'</p><p>Metric: '+esc(g.meta.metric)+'</p></section>').join('')+'<h3>30-day roadmap</h3>'+stages.map((s,i)=>'<h4>'+s+'</h4><p>'+m.grouped.filter(g=>g.meta.phase===i+1).map(g=>(done[g.rule]?'Completed: ':'Planned: ')+(edits[g.rule]??g.meta.fix)).join('; ')+(i===2?'Introduce recurring governance checks, reporting review and measurement of success metrics.':'')+'</p>').join('')+'<h3>Methodology and limitations</h3>'+coverage+'</div><button id="report-print" class="primary">Print / Save as PDF</button>'; $('report-print').onclick=()=>window.print();}}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-current',x===b?'page':'false'));render();});$('print-report').onclick=()=>{view='report';render();window.print();};const previousRun=$('run').onclick;$('run').onclick=()=>{previousRun();render();};const previousDemo=$('demo').onclick;$('demo').onclick=async()=>{await previousDemo();render();};const oldExport=$('export').onclick;$('export').onclick=()=>{let m=model();if(!m)return oldExport();let a=document.createElement('a'),u=URL.createObjectURL(new Blob([Ops.queue(m)],{type:'text/csv;charset=utf-8'}));a.href=u;a.download='recruiting-operations-repair-queue.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};document.addEventListener('health-data-loaded',()=>{edits={};done={};render();});document.addEventListener('health-invalidated',()=>{edits={};done={};render();});render();})();